-- ==== 0001_core.sql ====
-- 0001 Core: users, roles, company settings, document numbering, audit log

create type public.user_role as enum ('ADMIN', 'ACCOUNTANT', 'OPERATOR', 'VIEWER');

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null default '',
  email text,
  role public.user_role not null default 'VIEWER',
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

-- The first user to sign up becomes ADMIN; everyone after starts as VIEWER.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name, email, role)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    new.email,
    case when exists (select 1 from public.profiles) then 'VIEWER'::public.user_role else 'ADMIN'::public.user_role end
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
after insert on auth.users
for each row execute function public.handle_new_user();

create or replace function public.app_role()
returns public.user_role language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and is_active
$$;

create or replace function public.has_role(variadic roles public.user_role[])
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.app_role() = any(roles), false)
$$;

create or replace function public.require_role(variadic roles public.user_role[])
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role(variadic roles) then
    raise exception 'You do not have permission for this action' using errcode = '42501';
  end if;
end;
$$;

-- Company settings (single row)
create table public.company_settings (
  id int primary key default 1 check (id = 1),
  name text not null default 'My Rice Mill',
  name_bn text,
  address text,
  phone text,
  email text,
  header_image_url text,
  default_bag_kg numeric(10,3) not null default 50,
  invoice_footer text,
  updated_at timestamptz not null default now()
);

-- Document numbering: PUR-2026-00001 style, per type per year
create table public.doc_sequences (
  doc_type text not null,
  year int not null,
  last_no int not null default 0,
  primary key (doc_type, year)
);

create or replace function public.next_doc_no(p_doc_type text, p_date date)
returns text language plpgsql security definer set search_path = public as $$
declare
  v_year int := extract(year from p_date);
  v_no int;
begin
  insert into public.doc_sequences (doc_type, year, last_no)
  values (p_doc_type, v_year, 1)
  on conflict (doc_type, year) do update set last_no = public.doc_sequences.last_no + 1
  returning last_no into v_no;
  return p_doc_type || '-' || v_year || '-' || lpad(v_no::text, 5, '0');
end;
$$;

-- Audit log
create table public.audit_log (
  id bigint generated always as identity primary key,
  table_name text not null,
  row_id text,
  action text not null,
  old_data jsonb,
  new_data jsonb,
  user_id uuid default auth.uid() references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create or replace function public.audit_row()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.audit_log (table_name, row_id, action, old_data, new_data)
  values (
    tg_table_name,
    coalesce((case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end)->>'id', null),
    tg_op,
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end
  );
  return null;
end;
$$;

create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;


-- ==== 0002_master.sql ====
-- 0002 Master data: chart of accounts (incl. cash/bank and expense heads), parties, items, warehouses

create type public.account_type as enum ('ASSET', 'LIABILITY', 'EQUITY', 'INCOME', 'EXPENSE');

-- subtype drives behaviour:
--   CASH, BANK                 money accounts (cash book / bank book)
--   RECEIVABLE, PAYABLE        party control accounts
--   LOAN_PAYABLE, LOAN_RECEIVABLE
--   INVENTORY, WIP             stock and production in progress
--   SALES, SALES_RETURN, OTHER_INCOME, COGS, EXPENSE, STOCK_ADJUSTMENT
--   CAPITAL, DRAWINGS, OPENING_EQUITY
create table public.accounts (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  name_bn text,
  type public.account_type not null,
  subtype text not null,
  is_system boolean not null default false,
  is_active boolean not null default true,
  bank_name text,
  branch text,
  account_no text,
  opening_balance numeric(14,2) not null default 0,
  opening_date date not null default current_date,
  created_at timestamptz not null default now()
);

create index on public.accounts (subtype);

-- System account by subtype (first system account of that subtype)
create or replace function public.system_account(p_subtype text)
returns uuid language plpgsql stable security definer set search_path = public as $$
declare v_id uuid;
begin
  select id into v_id from public.accounts
  where subtype = p_subtype and is_system
  order by code limit 1;
  if v_id is null then
    raise exception 'System account % is missing', p_subtype;
  end if;
  return v_id;
end;
$$;

create table public.parties (
  id uuid primary key default gen_random_uuid(),
  code text unique,
  name text not null,
  name_bn text,
  phone text,
  address text,
  -- any of CUSTOMER, SUPPLIER, BROKER, TRANSPORTER, LENDER, EMPLOYEE, OTHER
  types text[] not null default '{}',
  -- positive: they owe us (receivable); negative: we owe them (payable)
  opening_balance numeric(14,2) not null default 0,
  opening_date date not null default current_date,
  credit_limit numeric(14,2),
  notes text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  constraint parties_types_valid check (
    types <@ array['CUSTOMER','SUPPLIER','BROKER','TRANSPORTER','LENDER','EMPLOYEE','OTHER']
  )
);

create index on public.parties using gin (types);

create type public.item_category as enum ('PADDY', 'RICE', 'BYPRODUCT', 'PACKAGING', 'OTHER');

create table public.items (
  id uuid primary key default gen_random_uuid(),
  code text unique,
  name text not null,
  name_bn text,
  category public.item_category not null,
  default_bag_kg numeric(10,3) not null default 50,
  -- reference price per kg, used to split production cost across outputs
  standard_price numeric(14,4) not null default 0,
  reorder_level_kg numeric(14,3),
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table public.warehouses (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  name_bn text,
  location text,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);


-- ==== 0003_accounting.sql ====
-- 0003 Accounting backbone: journal entries and lines, posting helpers, opening balances
--
-- Rule: party_id is set only on lines that hit a party control account
-- (RECEIVABLE, PAYABLE, LOAN_PAYABLE, LOAN_RECEIVABLE). A party's balance is therefore
-- sum(debit - credit) over its lines: positive = they owe us, negative = we owe them.

create table public.journal_entries (
  id uuid primary key default gen_random_uuid(),
  entry_date date not null,
  source_type text not null,
  source_id uuid,
  narration text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);

create index on public.journal_entries (source_type, source_id);
create index on public.journal_entries (entry_date);

create table public.journal_lines (
  id bigint generated always as identity primary key,
  entry_id uuid not null references public.journal_entries(id) on delete cascade,
  account_id uuid not null references public.accounts(id),
  party_id uuid references public.parties(id),
  debit numeric(14,2) not null default 0,
  credit numeric(14,2) not null default 0,
  memo text,
  constraint journal_lines_one_side check (debit >= 0 and credit >= 0 and (debit = 0 or credit = 0))
);

create index on public.journal_lines (account_id);
create index on public.journal_lines (party_id);
create index on public.journal_lines (entry_id);

-- Post a balanced entry. p_lines: [{account_id, party_id?, debit?, credit?, memo?}, ...]
-- Zero lines are skipped. Returns the entry id, or null when every line is zero.
create or replace function public.post_journal(
  p_date date, p_source_type text, p_source_id uuid, p_narration text, p_lines jsonb
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_entry uuid;
  v_dr numeric := 0;
  v_cr numeric := 0;
  l jsonb;
  v_debit numeric;
  v_credit numeric;
begin
  -- v_dr: net (debit - credit), must be zero; v_cr: total absolute movement
  for l in select * from jsonb_array_elements(p_lines) loop
    v_debit := round(coalesce((l->>'debit')::numeric, 0), 2) - round(coalesce((l->>'credit')::numeric, 0), 2);
    v_dr := v_dr + v_debit;
    v_cr := v_cr + abs(v_debit);
  end loop;

  if abs(v_dr) > 0.009 then
    raise exception 'Journal not balanced for % (difference %)', p_source_type, v_dr;
  end if;
  if v_cr = 0 then
    return null;
  end if;

  insert into public.journal_entries (entry_date, source_type, source_id, narration)
  values (p_date, p_source_type, p_source_id, p_narration)
  returning id into v_entry;

  for l in select * from jsonb_array_elements(p_lines) loop
    v_debit := round(coalesce((l->>'debit')::numeric, 0), 2);
    v_credit := round(coalesce((l->>'credit')::numeric, 0), 2);
    -- normalise negatives onto the other side
    if v_debit < 0 then v_credit := v_credit - v_debit; v_debit := 0; end if;
    if v_credit < 0 then v_debit := v_debit - v_credit; v_credit := 0; end if;
    if v_debit - v_credit <> 0 then
      insert into public.journal_lines (entry_id, account_id, party_id, debit, credit, memo)
      values (
        v_entry,
        (l->>'account_id')::uuid,
        nullif(l->>'party_id', '')::uuid,
        greatest(v_debit - v_credit, 0),
        greatest(v_credit - v_debit, 0),
        l->>'memo'
      );
    end if;
  end loop;

  return v_entry;
end;
$$;

create or replace function public.unpost_journal(p_source_type text, p_source_id uuid)
returns void language sql security definer set search_path = public as $$
  delete from public.journal_entries where source_type = p_source_type and source_id = p_source_id;
$$;

-- Small builders for journal lines
create or replace function public.jl_dr(p_account uuid, p_amount numeric, p_party uuid default null, p_memo text default null)
returns jsonb language sql immutable as $$
  select jsonb_build_object('account_id', p_account, 'party_id', p_party, 'debit', coalesce(p_amount, 0), 'memo', p_memo)
$$;

create or replace function public.jl_cr(p_account uuid, p_amount numeric, p_party uuid default null, p_memo text default null)
returns jsonb language sql immutable as $$
  select jsonb_build_object('account_id', p_account, 'party_id', p_party, 'credit', coalesce(p_amount, 0), 'memo', p_memo)
$$;

-- Opening balances: parties
create or replace function public.post_party_opening()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.unpost_journal('OPENING_PARTY', new.id);
  if new.opening_balance > 0 then
    perform public.post_journal(new.opening_date, 'OPENING_PARTY', new.id, 'Opening balance: ' || new.name, jsonb_build_array(
      public.jl_dr(public.system_account('RECEIVABLE'), new.opening_balance, new.id),
      public.jl_cr(public.system_account('OPENING_EQUITY'), new.opening_balance)
    ));
  elsif new.opening_balance < 0 then
    perform public.post_journal(new.opening_date, 'OPENING_PARTY', new.id, 'Opening balance: ' || new.name, jsonb_build_array(
      public.jl_dr(public.system_account('OPENING_EQUITY'), -new.opening_balance),
      public.jl_cr(public.system_account('PAYABLE'), -new.opening_balance, new.id)
    ));
  end if;
  return new;
end;
$$;

create trigger trg_party_opening
after insert or update of opening_balance, opening_date, name on public.parties
for each row execute function public.post_party_opening();

-- Opening balances: accounts (cash, bank, capital, loans, etc.)
create or replace function public.post_account_opening()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_eq uuid;
begin
  perform public.unpost_journal('OPENING_ACCOUNT', new.id);
  if new.opening_balance = 0 or new.subtype = 'OPENING_EQUITY' then
    return new;
  end if;
  v_eq := public.system_account('OPENING_EQUITY');
  -- Debit-normal accounts: assets and expenses
  if new.type in ('ASSET', 'EXPENSE') then
    perform public.post_journal(new.opening_date, 'OPENING_ACCOUNT', new.id, 'Opening balance: ' || new.name, jsonb_build_array(
      public.jl_dr(new.id, new.opening_balance), public.jl_cr(v_eq, new.opening_balance)));
  else
    perform public.post_journal(new.opening_date, 'OPENING_ACCOUNT', new.id, 'Opening balance: ' || new.name, jsonb_build_array(
      public.jl_dr(v_eq, new.opening_balance), public.jl_cr(new.id, new.opening_balance)));
  end if;
  return new;
end;
$$;

create trigger trg_account_opening
after insert or update of opening_balance, opening_date on public.accounts
for each row execute function public.post_account_opening();

-- Balances
create or replace view public.v_account_balances with (security_invoker = true) as
select
  a.*,
  coalesce(sum(l.debit), 0) as total_debit,
  coalesce(sum(l.credit), 0) as total_credit,
  coalesce(sum(l.debit - l.credit), 0) as balance
from public.accounts a
left join public.journal_lines l on l.account_id = a.id
group by a.id;

create or replace view public.v_party_balances with (security_invoker = true) as
select
  p.*,
  coalesce(sum(l.debit - l.credit), 0) as balance
from public.parties p
left join public.journal_lines l on l.party_id = p.id
group by p.id;


-- ==== 0004_stock.sql ====
-- 0004 Stock: lots, movements, FIFO consumption, transfers, adjustments
--
-- Quantities are kept in kg (the true measure) with bags alongside for counting.
-- Every receipt of goods creates a lot with a cost per kg. Every issue consumes lots
-- (FIFO unless a lot is picked) and records an allocation, so cost and profit can be
-- traced back to the exact purchase or production batch.

create table public.lots (
  id uuid primary key default gen_random_uuid(),
  lot_no text not null unique,
  item_id uuid not null references public.items(id),
  warehouse_id uuid not null references public.warehouses(id),
  -- PURCHASE, PRODUCTION, TRANSFER, SALE_RETURN, ADJUSTMENT
  source_type text not null,
  source_id uuid not null,
  received_date date not null,
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  bags numeric(12,2) not null default 0,
  bag_size_kg numeric(10,3) not null default 0,
  unit_cost numeric(18,6) not null default 0,
  remaining_kg numeric(14,3) not null,
  remaining_bags numeric(12,2) not null default 0,
  -- for transfers: the lot this one was split from, so profit traces back to the origin
  parent_lot_id uuid references public.lots(id),
  created_at timestamptz not null default now(),
  constraint lots_remaining_valid check (remaining_kg >= -0.0005 and remaining_kg <= qty_kg + 0.0005)
);

create index on public.lots (item_id, warehouse_id) where remaining_kg > 0;
create index on public.lots (source_type, source_id);

create table public.stock_movements (
  id bigint generated always as identity primary key,
  movement_date date not null,
  item_id uuid not null references public.items(id),
  warehouse_id uuid not null references public.warehouses(id),
  lot_id uuid references public.lots(id) on delete set null,
  qty_kg numeric(14,3) not null,      -- signed: + in, - out
  bags numeric(12,2) not null default 0,
  unit_cost numeric(18,6) not null default 0,
  value numeric(14,2) not null default 0,  -- signed
  source_type text not null,
  source_id uuid not null,
  source_line_id uuid,
  note text,
  created_at timestamptz not null default now()
);

create index on public.stock_movements (item_id, warehouse_id, movement_date);
create index on public.stock_movements (source_type, source_id);

-- What was taken from which lot, by which document line
create table public.lot_allocations (
  id bigint generated always as identity primary key,
  lot_id uuid not null references public.lots(id),
  qty_kg numeric(14,3) not null,
  bags numeric(12,2) not null default 0,
  cost numeric(14,2) not null,
  revenue numeric(14,2),   -- set for sales, used for lot profit
  source_type text not null,
  source_id uuid not null,
  source_line_id uuid,
  created_at timestamptz not null default now()
);

create index on public.lot_allocations (lot_id);
create index on public.lot_allocations (source_type, source_id);

-- Receive goods: create a lot and an inbound movement. Returns lot id.
create or replace function public.receive_stock(
  p_date date, p_item uuid, p_warehouse uuid, p_qty_kg numeric, p_bags numeric, p_bag_size numeric,
  p_unit_cost numeric, p_source_type text, p_source_id uuid, p_source_line_id uuid default null,
  p_parent_lot uuid default null, p_note text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_lot uuid;
begin
  if coalesce(p_qty_kg, 0) <= 0 then
    raise exception 'Quantity must be greater than zero';
  end if;
  insert into public.lots (lot_no, item_id, warehouse_id, source_type, source_id, received_date,
    qty_kg, bags, bag_size_kg, unit_cost, remaining_kg, remaining_bags, parent_lot_id)
  values (public.next_doc_no('LOT', p_date), p_item, p_warehouse, p_source_type, p_source_id, p_date,
    p_qty_kg, coalesce(p_bags, 0), coalesce(p_bag_size, 0), coalesce(p_unit_cost, 0), p_qty_kg, coalesce(p_bags, 0), p_parent_lot)
  returning id into v_lot;

  insert into public.stock_movements (movement_date, item_id, warehouse_id, lot_id, qty_kg, bags, unit_cost, value,
    source_type, source_id, source_line_id, note)
  values (p_date, p_item, p_warehouse, v_lot, p_qty_kg, coalesce(p_bags, 0), coalesce(p_unit_cost, 0),
    round(p_qty_kg * coalesce(p_unit_cost, 0), 2), p_source_type, p_source_id, p_source_line_id, p_note);
  return v_lot;
end;
$$;

-- Issue goods: consume from a specific lot or FIFO across lots of the item in the warehouse.
-- Records allocations (with revenue spread pro rata when given) and outbound movements.
-- Returns total cost of the goods issued.
create or replace function public.consume_stock(
  p_date date, p_item uuid, p_warehouse uuid, p_qty_kg numeric, p_bags numeric,
  p_source_type text, p_source_id uuid, p_source_line_id uuid default null,
  p_lot uuid default null, p_revenue numeric default null, p_note text default null
) returns numeric language plpgsql security definer set search_path = public as $$
declare
  v_left numeric := p_qty_kg;
  v_total_cost numeric := 0;
  v_take numeric;
  v_take_bags numeric;
  v_cost numeric;
  v_name text;
  r record;
begin
  if coalesce(p_qty_kg, 0) <= 0 then
    raise exception 'Quantity must be greater than zero';
  end if;

  for r in
    select * from public.lots
    where remaining_kg > 0.0005
      and (case when p_lot is not null then id = p_lot else item_id = p_item and warehouse_id = p_warehouse end)
    order by received_date, created_at
    for update
  loop
    exit when v_left <= 0.0005;
    v_take := least(r.remaining_kg, v_left);
    -- bags: share of the requested bags, or derived from the lot's bag size
    if coalesce(p_bags, 0) > 0 then
      v_take_bags := round(p_bags * v_take / p_qty_kg, 2);
    elsif r.bag_size_kg > 0 then
      v_take_bags := round(v_take / r.bag_size_kg, 2);
    else
      v_take_bags := 0;
    end if;
    v_take_bags := least(v_take_bags, r.remaining_bags);
    v_cost := round(v_take * r.unit_cost, 2);

    update public.lots
    set remaining_kg = remaining_kg - v_take, remaining_bags = greatest(remaining_bags - v_take_bags, 0)
    where id = r.id;

    insert into public.lot_allocations (lot_id, qty_kg, bags, cost, revenue, source_type, source_id, source_line_id)
    values (r.id, v_take, v_take_bags, v_cost,
      case when p_revenue is not null then round(p_revenue * v_take / p_qty_kg, 2) end,
      p_source_type, p_source_id, p_source_line_id);

    insert into public.stock_movements (movement_date, item_id, warehouse_id, lot_id, qty_kg, bags, unit_cost, value,
      source_type, source_id, source_line_id, note)
    values (p_date, r.item_id, r.warehouse_id, r.id, -v_take, -v_take_bags, r.unit_cost, -v_cost,
      p_source_type, p_source_id, p_source_line_id, p_note);

    v_left := v_left - v_take;
    v_total_cost := v_total_cost + v_cost;
  end loop;

  if v_left > 0.0005 then
    select name into v_name from public.items where id = p_item;
    raise exception 'Not enough stock of % (short by % kg)', coalesce(v_name, 'item'), round(v_left, 3);
  end if;

  return v_total_cost;
end;
$$;

-- Undo all stock effects of a document: give back consumed quantities, remove lots it created
-- (only if nothing has been taken from them yet) and delete its movements.
create or replace function public.unpost_stock(p_source_type text, p_source_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  r record;
begin
  for r in select * from public.lot_allocations where source_type = p_source_type and source_id = p_source_id loop
    update public.lots set remaining_kg = remaining_kg + r.qty_kg, remaining_bags = remaining_bags + r.bags
    where id = r.lot_id;
  end loop;
  delete from public.lot_allocations where source_type = p_source_type and source_id = p_source_id;

  if exists (
    select 1 from public.lots l
    where l.source_type = p_source_type and l.source_id = p_source_id
      and (exists (select 1 from public.lot_allocations a where a.lot_id = l.id)
           or exists (select 1 from public.lots c where c.parent_lot_id = l.id))
  ) then
    raise exception 'Stock from this document has already been sold, milled or moved. Reverse those first.';
  end if;

  delete from public.stock_movements where source_type = p_source_type and source_id = p_source_id;
  delete from public.lots where source_type = p_source_type and source_id = p_source_id;
end;
$$;

-- Warehouse transfers: lot-by-lot, keeping cost; no accounting effect
create table public.stock_transfers (
  id uuid primary key default gen_random_uuid(),
  transfer_no text not null unique,
  transfer_date date not null,
  item_id uuid not null references public.items(id),
  from_warehouse_id uuid not null references public.warehouses(id),
  to_warehouse_id uuid not null references public.warehouses(id),
  lot_id uuid references public.lots(id),
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  bags numeric(12,2) not null default 0,
  notes text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  constraint transfer_different check (from_warehouse_id <> to_warehouse_id)
);

create or replace function public.save_stock_transfer(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_t public.stock_transfers;
  a record;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  if v_id is not null then
    perform public.delete_stock_transfer(v_id);
  end if;

  insert into public.stock_transfers (id, transfer_no, transfer_date, item_id, from_warehouse_id, to_warehouse_id,
    lot_id, qty_kg, bags, notes)
  values (coalesce(v_id, gen_random_uuid()),
    coalesce(nullif(p->>'transfer_no', ''), public.next_doc_no('TRF', (p->>'transfer_date')::date)),
    (p->>'transfer_date')::date, (p->>'item_id')::uuid, (p->>'from_warehouse_id')::uuid, (p->>'to_warehouse_id')::uuid,
    nullif(p->>'lot_id', '')::uuid, (p->>'qty_kg')::numeric, coalesce((p->>'bags')::numeric, 0), p->>'notes')
  returning * into v_t;

  perform public.consume_stock(v_t.transfer_date, v_t.item_id, v_t.from_warehouse_id, v_t.qty_kg, v_t.bags,
    'TRANSFER', v_t.id, null, v_t.lot_id, null, 'Transfer out');

  -- recreate each consumed slice as a new lot in the destination, same cost
  for a in
    select al.*, l.unit_cost, l.bag_size_kg, l.item_id from public.lot_allocations al
    join public.lots l on l.id = al.lot_id
    where al.source_type = 'TRANSFER' and al.source_id = v_t.id
  loop
    perform public.receive_stock(v_t.transfer_date, a.item_id, v_t.to_warehouse_id, a.qty_kg, a.bags, a.bag_size_kg,
      a.unit_cost, 'TRANSFER', v_t.id, null, a.lot_id, 'Transfer in');
  end loop;
  return v_t.id;
end;
$$;

create or replace function public.delete_stock_transfer(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  -- the destination lots must be untouched; check them before giving stock back
  if exists (
    select 1 from public.lots l where l.source_type = 'TRANSFER' and l.source_id = p_id and l.parent_lot_id is not null
      and (exists (select 1 from public.lot_allocations a where a.lot_id = l.id)
           or exists (select 1 from public.lots c where c.parent_lot_id = l.id))
  ) then
    raise exception 'Transferred stock has already been used. Reverse that first.';
  end if;
  delete from public.stock_movements where source_type = 'TRANSFER' and source_id = p_id and qty_kg > 0;
  delete from public.lots where source_type = 'TRANSFER' and source_id = p_id;
  perform public.unpost_stock('TRANSFER', p_id);
  delete from public.stock_transfers where id = p_id;
end;
$$;

-- Adjustments: OPENING stock, GAIN (found/excess), LOSS (shortage, damage, drying loss)
create table public.stock_adjustments (
  id uuid primary key default gen_random_uuid(),
  adjustment_no text not null unique,
  adjustment_date date not null,
  kind text not null check (kind in ('OPENING', 'GAIN', 'LOSS')),
  item_id uuid not null references public.items(id),
  warehouse_id uuid not null references public.warehouses(id),
  lot_id uuid references public.lots(id),
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  bags numeric(12,2) not null default 0,
  bag_size_kg numeric(10,3) not null default 0,
  unit_cost numeric(18,6) not null default 0,
  value numeric(14,2) not null default 0,
  reason text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);

create or replace function public.save_stock_adjustment(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_a public.stock_adjustments;
  v_value numeric;
  v_inv uuid := public.system_account('INVENTORY');
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  if v_id is not null then
    perform public.delete_stock_adjustment(v_id);
  end if;

  insert into public.stock_adjustments (id, adjustment_no, adjustment_date, kind, item_id, warehouse_id, lot_id,
    qty_kg, bags, bag_size_kg, unit_cost, reason)
  values (coalesce(v_id, gen_random_uuid()),
    coalesce(nullif(p->>'adjustment_no', ''), public.next_doc_no('ADJ', (p->>'adjustment_date')::date)),
    (p->>'adjustment_date')::date, p->>'kind', (p->>'item_id')::uuid, (p->>'warehouse_id')::uuid,
    nullif(p->>'lot_id', '')::uuid, (p->>'qty_kg')::numeric, coalesce((p->>'bags')::numeric, 0),
    coalesce((p->>'bag_size_kg')::numeric, 0), coalesce((p->>'unit_cost')::numeric, 0), p->>'reason')
  returning * into v_a;

  if v_a.kind = 'LOSS' then
    v_value := public.consume_stock(v_a.adjustment_date, v_a.item_id, v_a.warehouse_id, v_a.qty_kg, v_a.bags,
      'ADJUSTMENT', v_a.id, null, v_a.lot_id, null, coalesce(v_a.reason, 'Stock loss'));
    perform public.post_journal(v_a.adjustment_date, 'ADJUSTMENT', v_a.id, 'Stock loss ' || v_a.adjustment_no, jsonb_build_array(
      public.jl_dr(public.system_account('STOCK_ADJUSTMENT'), v_value), public.jl_cr(v_inv, v_value)));
  else
    perform public.receive_stock(v_a.adjustment_date, v_a.item_id, v_a.warehouse_id, v_a.qty_kg, v_a.bags,
      v_a.bag_size_kg, v_a.unit_cost, 'ADJUSTMENT', v_a.id, null, null, v_a.reason);
    v_value := round(v_a.qty_kg * v_a.unit_cost, 2);
    perform public.post_journal(v_a.adjustment_date, 'ADJUSTMENT', v_a.id,
      case v_a.kind when 'OPENING' then 'Opening stock ' else 'Stock gain ' end || v_a.adjustment_no,
      jsonb_build_array(
        public.jl_dr(v_inv, v_value),
        public.jl_cr(public.system_account(case v_a.kind when 'OPENING' then 'OPENING_EQUITY' else 'STOCK_ADJUSTMENT' end), v_value)));
  end if;

  update public.stock_adjustments set value = v_value where id = v_a.id;
  return v_a.id;
end;
$$;

create or replace function public.delete_stock_adjustment(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  perform public.unpost_stock('ADJUSTMENT', p_id);
  perform public.unpost_journal('ADJUSTMENT', p_id);
  delete from public.stock_adjustments where id = p_id;
end;
$$;

-- Views
create or replace view public.v_stock_summary with (security_invoker = true) as
select
  i.id as item_id, i.name as item_name, i.name_bn as item_name_bn, i.category,
  w.id as warehouse_id, w.name as warehouse_name, w.name_bn as warehouse_name_bn,
  sum(l.remaining_kg) as qty_kg,
  sum(l.remaining_bags) as bags,
  round(sum(l.remaining_kg * l.unit_cost), 2) as value,
  case when sum(l.remaining_kg) > 0 then round(sum(l.remaining_kg * l.unit_cost) / sum(l.remaining_kg), 4) else 0 end as avg_cost,
  i.reorder_level_kg
from public.lots l
join public.items i on i.id = l.item_id
join public.warehouses w on w.id = l.warehouse_id
where l.remaining_kg > 0.0005
group by i.id, w.id;

create or replace view public.v_lots with (security_invoker = true) as
select
  l.*, i.name as item_name, i.name_bn as item_name_bn, i.category,
  w.name as warehouse_name, w.name_bn as warehouse_name_bn
from public.lots l
join public.items i on i.id = l.item_id
join public.warehouses w on w.id = l.warehouse_id;


-- ==== 0005_trading.sql ====
-- 0005 Trading: purchases, sales, returns
--
-- Each document is saved through one function that takes the whole document as JSON,
-- writes header and lines, and posts stock and journal entries in the same transaction.
-- Editing a document first reverses its previous effects, then posts it again.

-- Line amount: rate is per kg or per bag
create or replace function public.line_amount(p_rate_unit text, p_rate numeric, p_qty_kg numeric, p_bags numeric)
returns numeric language sql immutable as $$
  select round(coalesce(p_rate, 0) * case when p_rate_unit = 'BAG' then coalesce(p_bags, 0) else coalesce(p_qty_kg, 0) end, 2)
$$;

------------------------------------------------------------------------------------------
-- Purchases
------------------------------------------------------------------------------------------
create table public.purchases (
  id uuid primary key default gen_random_uuid(),
  purchase_no text not null unique,
  purchase_date date not null,
  supplier_id uuid not null references public.parties(id),
  broker_id uuid references public.parties(id),
  warehouse_id uuid not null references public.warehouses(id),
  vehicle_no text,
  reference text,
  notes text,
  goods_amount numeric(14,2) not null default 0,       -- sum of lines
  discount numeric(14,2) not null default 0,           -- reduces supplier bill
  supplier_total numeric(14,2) not null default 0,     -- goods - discount, owed to supplier
  transport_cost numeric(14,2) not null default 0,     -- added to stock cost
  labour_cost numeric(14,2) not null default 0,        -- added to stock cost
  other_cost numeric(14,2) not null default 0,         -- added to stock cost
  costs_account_id uuid references public.accounts(id),-- cash/bank that paid the extra costs; null = added to supplier bill
  commission_amount numeric(14,2) not null default 0,  -- owed to broker, added to stock cost
  paid_amount numeric(14,2) not null default 0,        -- paid to supplier at purchase time
  paid_account_id uuid references public.accounts(id),
  total_cost numeric(14,2) not null default 0,         -- landed cost of all goods
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on public.purchases (supplier_id);
create index on public.purchases (purchase_date);

create table public.purchase_lines (
  id uuid primary key default gen_random_uuid(),
  purchase_id uuid not null references public.purchases(id) on delete cascade,
  line_no int not null,
  item_id uuid not null references public.items(id),
  bags numeric(12,2) not null default 0,
  bag_size_kg numeric(10,3) not null default 0,
  gross_kg numeric(14,3) not null,
  deduction_kg numeric(14,3) not null default 0,  -- moisture, bag weight, dust
  net_kg numeric(14,3) not null,
  rate numeric(14,4) not null,
  rate_unit text not null default 'KG' check (rate_unit in ('KG', 'BAG')),
  amount numeric(14,2) not null,
  unit_cost numeric(18,6) not null default 0,     -- landed cost per kg
  lot_id uuid references public.lots(id) on delete set null
);

create index on public.purchase_lines (purchase_id);

create or replace function public.post_purchase(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  h public.purchases;
  r public.purchase_lines;
  v_extra numeric;
  v_lot uuid;
  v_unit numeric;
  v_inv uuid := public.system_account('INVENTORY');
  v_ap uuid := public.system_account('PAYABLE');
  v_lines jsonb;
begin
  select * into h from public.purchases where id = p_id;
  v_extra := h.transport_cost + h.labour_cost + h.other_cost + h.commission_amount;

  -- stock: spread extra costs across lines by value
  for r in select * from public.purchase_lines where purchase_id = p_id order by line_no loop
    v_unit := case when r.net_kg > 0 then
      (r.amount + case when h.goods_amount > 0 then v_extra * r.amount / h.goods_amount else 0 end
                - case when h.goods_amount > 0 then h.discount * r.amount / h.goods_amount else 0 end) / r.net_kg
      else 0 end;
    v_lot := public.receive_stock(h.purchase_date, r.item_id, h.warehouse_id, r.net_kg, r.bags, r.bag_size_kg,
      v_unit, 'PURCHASE', h.id, r.id, null, h.purchase_no);
    update public.purchase_lines set lot_id = v_lot, unit_cost = round(v_unit, 6) where id = r.id;
  end loop;

  -- journal
  v_lines := jsonb_build_array(
    public.jl_dr(v_inv, h.total_cost, null, 'Goods received'),
    public.jl_cr(v_ap, h.goods_amount - h.discount, h.supplier_id, 'Supplier bill')
  );
  if h.commission_amount > 0 then
    if h.broker_id is null then
      raise exception 'Choose the broker to pay commission to';
    end if;
    v_lines := v_lines || public.jl_cr(v_ap, h.commission_amount, h.broker_id, 'Broker commission');
  end if;
  if h.transport_cost + h.labour_cost + h.other_cost > 0 then
    if h.costs_account_id is not null then
      v_lines := v_lines || public.jl_cr(h.costs_account_id, h.transport_cost + h.labour_cost + h.other_cost, null, 'Transport and labour');
    else
      v_lines := v_lines || public.jl_cr(v_ap, h.transport_cost + h.labour_cost + h.other_cost, h.supplier_id, 'Transport and labour');
    end if;
  end if;
  if h.paid_amount > 0 then
    if h.paid_account_id is null then
      raise exception 'Choose the cash or bank account the payment was made from';
    end if;
    v_lines := v_lines
      || public.jl_dr(v_ap, h.paid_amount, h.supplier_id, 'Paid at purchase')
      || public.jl_cr(h.paid_account_id, h.paid_amount, null, 'Paid at purchase');
  end if;

  perform public.post_journal(h.purchase_date, 'PURCHASE', h.id, 'Purchase ' || h.purchase_no, v_lines);
end;
$$;

create or replace function public.unpost_purchase(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.unpost_stock('PURCHASE', p_id);
  perform public.unpost_journal('PURCHASE', p_id);
end;
$$;

create or replace function public.save_purchase(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'purchase_date')::date;
  v_no text := nullif(p->>'purchase_no', '');
  l jsonb;
  v_i int := 0;
  v_goods numeric := 0;
  v_net numeric;
  v_amount numeric;
  h public.purchases;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  if jsonb_array_length(coalesce(p->'lines', '[]'::jsonb)) = 0 then
    raise exception 'Add at least one item';
  end if;

  if v_id is not null then
    perform public.unpost_purchase(v_id);
    delete from public.purchase_lines where purchase_id = v_id;
    select purchase_no into v_no from public.purchases where id = v_id;
  else
    v_id := gen_random_uuid();
  end if;

  insert into public.purchases (id, purchase_no, purchase_date, supplier_id, broker_id, warehouse_id, vehicle_no, reference, notes,
    discount, transport_cost, labour_cost, other_cost, costs_account_id, commission_amount, paid_amount, paid_account_id)
  values (v_id, coalesce(v_no, public.next_doc_no('PUR', v_date)), v_date, (p->>'supplier_id')::uuid,
    nullif(p->>'broker_id', '')::uuid, (p->>'warehouse_id')::uuid, p->>'vehicle_no', p->>'reference', p->>'notes',
    coalesce((p->>'discount')::numeric, 0), coalesce((p->>'transport_cost')::numeric, 0),
    coalesce((p->>'labour_cost')::numeric, 0), coalesce((p->>'other_cost')::numeric, 0),
    nullif(p->>'costs_account_id', '')::uuid, coalesce((p->>'commission_amount')::numeric, 0),
    coalesce((p->>'paid_amount')::numeric, 0), nullif(p->>'paid_account_id', '')::uuid)
  on conflict (id) do update set
    purchase_date = excluded.purchase_date, supplier_id = excluded.supplier_id, broker_id = excluded.broker_id,
    warehouse_id = excluded.warehouse_id, vehicle_no = excluded.vehicle_no, reference = excluded.reference,
    notes = excluded.notes, discount = excluded.discount, transport_cost = excluded.transport_cost,
    labour_cost = excluded.labour_cost, other_cost = excluded.other_cost, costs_account_id = excluded.costs_account_id,
    commission_amount = excluded.commission_amount, paid_amount = excluded.paid_amount,
    paid_account_id = excluded.paid_account_id, updated_at = now();

  for l in select * from jsonb_array_elements(p->'lines') loop
    v_i := v_i + 1;
    v_net := coalesce((l->>'gross_kg')::numeric, 0) - coalesce((l->>'deduction_kg')::numeric, 0);
    if v_net <= 0 then
      raise exception 'Line %: net weight must be greater than zero', v_i;
    end if;
    v_amount := public.line_amount(coalesce(l->>'rate_unit', 'KG'), (l->>'rate')::numeric, v_net, (l->>'bags')::numeric);
    insert into public.purchase_lines (purchase_id, line_no, item_id, bags, bag_size_kg, gross_kg, deduction_kg, net_kg,
      rate, rate_unit, amount)
    values (v_id, v_i, (l->>'item_id')::uuid, coalesce((l->>'bags')::numeric, 0), coalesce((l->>'bag_size_kg')::numeric, 0),
      (l->>'gross_kg')::numeric, coalesce((l->>'deduction_kg')::numeric, 0), v_net,
      coalesce((l->>'rate')::numeric, 0), coalesce(l->>'rate_unit', 'KG'), v_amount);
    v_goods := v_goods + v_amount;
  end loop;

  update public.purchases set
    goods_amount = v_goods,
    supplier_total = v_goods - discount
      + case when costs_account_id is null then transport_cost + labour_cost + other_cost else 0 end,
    total_cost = v_goods - discount + transport_cost + labour_cost + other_cost + commission_amount
  where id = v_id
  returning * into h;

  if h.paid_amount > h.supplier_total then
    raise exception 'Paid amount is more than the supplier bill';
  end if;

  perform public.post_purchase(v_id);
  return v_id;
end;
$$;

create or replace function public.delete_purchase(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  perform public.unpost_purchase(p_id);
  delete from public.purchases where id = p_id;
end;
$$;

------------------------------------------------------------------------------------------
-- Sales
------------------------------------------------------------------------------------------
create table public.sales (
  id uuid primary key default gen_random_uuid(),
  sale_no text not null unique,
  sale_date date not null,
  customer_id uuid not null references public.parties(id),
  broker_id uuid references public.parties(id),
  warehouse_id uuid not null references public.warehouses(id),
  vehicle_no text,
  driver_name text,
  driver_phone text,
  reference text,
  notes text,
  goods_amount numeric(14,2) not null default 0,
  transport_charge numeric(14,2) not null default 0,   -- charged to customer
  labour_charge numeric(14,2) not null default 0,      -- charged to customer
  discount numeric(14,2) not null default 0,
  total_amount numeric(14,2) not null default 0,       -- customer owes this
  commission_amount numeric(14,2) not null default 0,  -- owed to broker, selling expense
  received_amount numeric(14,2) not null default 0,
  received_account_id uuid references public.accounts(id),
  cost_amount numeric(14,2) not null default 0,        -- cost of goods sold
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on public.sales (customer_id);
create index on public.sales (sale_date);

create table public.sale_lines (
  id uuid primary key default gen_random_uuid(),
  sale_id uuid not null references public.sales(id) on delete cascade,
  line_no int not null,
  item_id uuid not null references public.items(id),
  lot_id uuid references public.lots(id),      -- picked lot, or null for FIFO
  bags numeric(12,2) not null default 0,
  bag_size_kg numeric(10,3) not null default 0,
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  rate numeric(14,4) not null,
  rate_unit text not null default 'KG' check (rate_unit in ('KG', 'BAG')),
  amount numeric(14,2) not null,
  cost_amount numeric(14,2) not null default 0
);

create index on public.sale_lines (sale_id);

create or replace function public.post_sale(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  h public.sales;
  r public.sale_lines;
  v_cost numeric;
  v_total_cost numeric := 0;
  v_ar uuid := public.system_account('RECEIVABLE');
  v_lines jsonb;
begin
  select * into h from public.sales where id = p_id;

  for r in select * from public.sale_lines where sale_id = p_id order by line_no loop
    v_cost := public.consume_stock(h.sale_date, r.item_id, h.warehouse_id, r.qty_kg, r.bags,
      'SALE', h.id, r.id, r.lot_id,
      -- revenue for lot profit: line amount less its share of discount
      r.amount - case when h.goods_amount > 0 then h.discount * r.amount / h.goods_amount else 0 end,
      h.sale_no);
    update public.sale_lines set cost_amount = v_cost where id = r.id;
    v_total_cost := v_total_cost + v_cost;
  end loop;
  update public.sales set cost_amount = v_total_cost where id = p_id;

  v_lines := jsonb_build_array(
    public.jl_dr(v_ar, h.total_amount, h.customer_id, 'Sale'),
    public.jl_cr(public.system_account('SALES'), h.goods_amount - h.discount, null, 'Sales'),
    public.jl_cr(public.system_account('OTHER_INCOME'), h.transport_charge + h.labour_charge, null, 'Transport and labour charged'),
    public.jl_dr(public.system_account('COGS'), v_total_cost, null, 'Cost of goods sold'),
    public.jl_cr(public.system_account('INVENTORY'), v_total_cost, null, 'Goods issued')
  );
  if h.commission_amount > 0 then
    if h.broker_id is null then
      raise exception 'Choose the broker to pay commission to';
    end if;
    v_lines := v_lines
      || public.jl_dr(public.system_account('COMMISSION'), h.commission_amount, null, 'Broker commission')
      || public.jl_cr(public.system_account('PAYABLE'), h.commission_amount, h.broker_id, 'Broker commission');
  end if;
  if h.received_amount > 0 then
    if h.received_account_id is null then
      raise exception 'Choose the cash or bank account the money was received into';
    end if;
    v_lines := v_lines
      || public.jl_dr(h.received_account_id, h.received_amount, null, 'Received at sale')
      || public.jl_cr(v_ar, h.received_amount, h.customer_id, 'Received at sale');
  end if;

  perform public.post_journal(h.sale_date, 'SALE', h.id, 'Sale ' || h.sale_no, v_lines);
end;
$$;

create or replace function public.unpost_sale(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.sale_returns where sale_id = p_id) then
    raise exception 'This sale has returns. Delete the returns first.';
  end if;
  perform public.unpost_stock('SALE', p_id);
  perform public.unpost_journal('SALE', p_id);
end;
$$;

create or replace function public.save_sale(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'sale_date')::date;
  v_no text := nullif(p->>'sale_no', '');
  l jsonb;
  v_i int := 0;
  v_goods numeric := 0;
  v_amount numeric;
  h public.sales;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  if jsonb_array_length(coalesce(p->'lines', '[]'::jsonb)) = 0 then
    raise exception 'Add at least one item';
  end if;

  if v_id is not null then
    perform public.unpost_sale(v_id);
    delete from public.sale_lines where sale_id = v_id;
    select sale_no into v_no from public.sales where id = v_id;
  else
    v_id := gen_random_uuid();
  end if;

  insert into public.sales (id, sale_no, sale_date, customer_id, broker_id, warehouse_id, vehicle_no, driver_name, driver_phone,
    reference, notes, transport_charge, labour_charge, discount, commission_amount, received_amount, received_account_id)
  values (v_id, coalesce(v_no, public.next_doc_no('SAL', v_date)), v_date, (p->>'customer_id')::uuid,
    nullif(p->>'broker_id', '')::uuid, (p->>'warehouse_id')::uuid, p->>'vehicle_no', p->>'driver_name', p->>'driver_phone',
    p->>'reference', p->>'notes', coalesce((p->>'transport_charge')::numeric, 0), coalesce((p->>'labour_charge')::numeric, 0),
    coalesce((p->>'discount')::numeric, 0), coalesce((p->>'commission_amount')::numeric, 0),
    coalesce((p->>'received_amount')::numeric, 0), nullif(p->>'received_account_id', '')::uuid)
  on conflict (id) do update set
    sale_date = excluded.sale_date, customer_id = excluded.customer_id, broker_id = excluded.broker_id,
    warehouse_id = excluded.warehouse_id, vehicle_no = excluded.vehicle_no, driver_name = excluded.driver_name,
    driver_phone = excluded.driver_phone, reference = excluded.reference, notes = excluded.notes,
    transport_charge = excluded.transport_charge, labour_charge = excluded.labour_charge, discount = excluded.discount,
    commission_amount = excluded.commission_amount, received_amount = excluded.received_amount,
    received_account_id = excluded.received_account_id, updated_at = now();

  for l in select * from jsonb_array_elements(p->'lines') loop
    v_i := v_i + 1;
    v_amount := public.line_amount(coalesce(l->>'rate_unit', 'KG'), (l->>'rate')::numeric, (l->>'qty_kg')::numeric, (l->>'bags')::numeric);
    insert into public.sale_lines (sale_id, line_no, item_id, lot_id, bags, bag_size_kg, qty_kg, rate, rate_unit, amount)
    values (v_id, v_i, (l->>'item_id')::uuid, nullif(l->>'lot_id', '')::uuid, coalesce((l->>'bags')::numeric, 0),
      coalesce((l->>'bag_size_kg')::numeric, 0), (l->>'qty_kg')::numeric, coalesce((l->>'rate')::numeric, 0),
      coalesce(l->>'rate_unit', 'KG'), v_amount);
    v_goods := v_goods + v_amount;
  end loop;

  update public.sales set
    goods_amount = v_goods,
    total_amount = v_goods - discount + transport_charge + labour_charge
  where id = v_id
  returning * into h;

  if h.received_amount > h.total_amount then
    raise exception 'Received amount is more than the invoice total';
  end if;

  perform public.post_sale(v_id);
  return v_id;
end;
$$;

create or replace function public.delete_sale(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  perform public.unpost_sale(p_id);
  delete from public.sales where id = p_id;
end;
$$;

------------------------------------------------------------------------------------------
-- Returns
------------------------------------------------------------------------------------------
-- Sale return: goods come back into stock at their original cost; customer is credited.
create table public.sale_returns (
  id uuid primary key default gen_random_uuid(),
  return_no text not null unique,
  return_date date not null,
  sale_id uuid references public.sales(id),
  customer_id uuid not null references public.parties(id),
  warehouse_id uuid not null references public.warehouses(id),
  item_id uuid not null references public.items(id),
  bags numeric(12,2) not null default 0,
  bag_size_kg numeric(10,3) not null default 0,
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  amount numeric(14,2) not null,      -- credited to customer
  unit_cost numeric(18,6) not null default 0,
  reason text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);

create or replace function public.save_sale_return(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := coalesce(nullif(p->>'id', '')::uuid, gen_random_uuid());
  v_unit numeric;
  r public.sale_returns;
  v_cost numeric;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  if exists (select 1 from public.sale_returns where id = v_id) then
    perform public.delete_sale_return(v_id);
  end if;

  -- cost: average cost per kg of this item in the original sale, else the item's standard price
  select case when sum(qty_kg) > 0 then sum(cost_amount) / sum(qty_kg) end into v_unit
  from public.sale_lines where sale_id = nullif(p->>'sale_id', '')::uuid and item_id = (p->>'item_id')::uuid;
  if v_unit is null then
    select standard_price into v_unit from public.items where id = (p->>'item_id')::uuid;
  end if;

  insert into public.sale_returns (id, return_no, return_date, sale_id, customer_id, warehouse_id, item_id, bags, bag_size_kg,
    qty_kg, amount, unit_cost, reason)
  values (v_id, coalesce(nullif(p->>'return_no', ''), public.next_doc_no('SRT', (p->>'return_date')::date)),
    (p->>'return_date')::date, nullif(p->>'sale_id', '')::uuid, (p->>'customer_id')::uuid, (p->>'warehouse_id')::uuid,
    (p->>'item_id')::uuid, coalesce((p->>'bags')::numeric, 0), coalesce((p->>'bag_size_kg')::numeric, 0),
    (p->>'qty_kg')::numeric, (p->>'amount')::numeric, round(v_unit, 6), p->>'reason')
  returning * into r;

  perform public.receive_stock(r.return_date, r.item_id, r.warehouse_id, r.qty_kg, r.bags, r.bag_size_kg, r.unit_cost,
    'SALE_RETURN', r.id, null, null, r.return_no);
  v_cost := round(r.qty_kg * r.unit_cost, 2);

  perform public.post_journal(r.return_date, 'SALE_RETURN', r.id, 'Sale return ' || r.return_no, jsonb_build_array(
    public.jl_dr(public.system_account('SALES_RETURN'), r.amount),
    public.jl_cr(public.system_account('RECEIVABLE'), r.amount, r.customer_id),
    public.jl_dr(public.system_account('INVENTORY'), v_cost),
    public.jl_cr(public.system_account('COGS'), v_cost)
  ));
  return r.id;
end;
$$;

create or replace function public.delete_sale_return(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  perform public.unpost_stock('SALE_RETURN', p_id);
  perform public.unpost_journal('SALE_RETURN', p_id);
  delete from public.sale_returns where id = p_id;
end;
$$;

-- Purchase return: goods go back to the supplier; supplier bill is reduced.
create table public.purchase_returns (
  id uuid primary key default gen_random_uuid(),
  return_no text not null unique,
  return_date date not null,
  purchase_id uuid references public.purchases(id),
  supplier_id uuid not null references public.parties(id),
  warehouse_id uuid not null references public.warehouses(id),
  item_id uuid not null references public.items(id),
  lot_id uuid references public.lots(id),
  bags numeric(12,2) not null default 0,
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  amount numeric(14,2) not null,      -- debited to supplier
  cost_amount numeric(14,2) not null default 0,
  reason text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);

create or replace function public.save_purchase_return(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := coalesce(nullif(p->>'id', '')::uuid, gen_random_uuid());
  r public.purchase_returns;
  v_cost numeric;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  if exists (select 1 from public.purchase_returns where id = v_id) then
    perform public.delete_purchase_return(v_id);
  end if;

  insert into public.purchase_returns (id, return_no, return_date, purchase_id, supplier_id, warehouse_id, item_id, lot_id,
    bags, qty_kg, amount, reason)
  values (v_id, coalesce(nullif(p->>'return_no', ''), public.next_doc_no('PRT', (p->>'return_date')::date)),
    (p->>'return_date')::date, nullif(p->>'purchase_id', '')::uuid, (p->>'supplier_id')::uuid, (p->>'warehouse_id')::uuid,
    (p->>'item_id')::uuid, nullif(p->>'lot_id', '')::uuid, coalesce((p->>'bags')::numeric, 0), (p->>'qty_kg')::numeric,
    (p->>'amount')::numeric, p->>'reason')
  returning * into r;

  v_cost := public.consume_stock(r.return_date, r.item_id, r.warehouse_id, r.qty_kg, r.bags, 'PURCHASE_RETURN', r.id,
    null, r.lot_id, null, r.return_no);
  update public.purchase_returns set cost_amount = v_cost where id = r.id;

  -- difference between what the supplier credits us and the stock cost goes to cost of goods sold
  perform public.post_journal(r.return_date, 'PURCHASE_RETURN', r.id, 'Purchase return ' || r.return_no, jsonb_build_array(
    public.jl_dr(public.system_account('PAYABLE'), r.amount, r.supplier_id),
    public.jl_cr(public.system_account('INVENTORY'), v_cost),
    public.jl_cr(public.system_account('COGS'), r.amount - v_cost)
  ));
  return r.id;
end;
$$;

create or replace function public.delete_purchase_return(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  perform public.unpost_stock('PURCHASE_RETURN', p_id);
  perform public.unpost_journal('PURCHASE_RETURN', p_id);
  delete from public.purchase_returns where id = p_id;
end;
$$;


-- ==== 0006_production.sql ====
-- 0006 Mill production: batches through soaking/parboiling, drying and milling
--
-- Flow:
--   1. Start a batch with paddy inputs: paddy leaves stock, its cost moves into
--      Work in Process (WIP).
--   2. Record each stage (dates, kg in/out, moisture) and its costs (fuel, labour,
--      electricity...). Costs are added to WIP.
--   3. Complete the batch with outputs (rice grades, broken rice, bran, husk). WIP cost
--      is split across outputs by relative value (qty x item standard price) and each
--      output becomes a new stock lot.

create type public.production_status as enum ('SOAKING', 'DRYING', 'MILLING', 'COMPLETED', 'CANCELLED');

create table public.production_batches (
  id uuid primary key default gen_random_uuid(),
  batch_no text not null unique,
  start_date date not null,
  status public.production_status not null default 'SOAKING',
  input_warehouse_id uuid not null references public.warehouses(id),
  output_warehouse_id uuid not null references public.warehouses(id),
  notes text,
  input_kg numeric(14,3) not null default 0,
  input_cost numeric(14,2) not null default 0,
  processing_cost numeric(14,2) not null default 0,
  output_kg numeric(14,3) not null default 0,
  completed_date date,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.production_inputs (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.production_batches(id) on delete cascade,
  item_id uuid not null references public.items(id),
  lot_id uuid references public.lots(id),   -- picked lot, or null for FIFO
  bags numeric(12,2) not null default 0,
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  cost numeric(14,2) not null default 0
);

create table public.production_stages (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.production_batches(id) on delete cascade,
  stage text not null check (stage in ('SOAKING', 'DRYING', 'MILLING')),
  start_date date,
  end_date date,
  input_kg numeric(14,3),
  output_kg numeric(14,3),
  moisture_pct numeric(5,2),
  notes text,
  unique (batch_id, stage)
);

create table public.production_costs (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.production_batches(id) on delete cascade,
  stage text not null check (stage in ('SOAKING', 'DRYING', 'MILLING', 'GENERAL')),
  cost_date date not null,
  cost_head_id uuid not null references public.accounts(id),   -- expense head for reporting (fuel, labour...)
  amount numeric(14,2) not null check (amount > 0),
  paid_account_id uuid references public.accounts(id),         -- cash/bank, or
  party_id uuid references public.parties(id),                 -- owed to this party
  notes text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  constraint production_cost_paid_by check (paid_account_id is not null or party_id is not null)
);

create table public.production_outputs (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.production_batches(id) on delete cascade,
  item_id uuid not null references public.items(id),
  bags numeric(12,2) not null default 0,
  bag_size_kg numeric(10,3) not null default 0,
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  cost_share numeric(14,2) not null default 0,
  unit_cost numeric(18,6) not null default 0,
  lot_id uuid references public.lots(id) on delete set null
);

create or replace function public.require_open_batch(p_id uuid)
returns public.production_batches language plpgsql security definer set search_path = public as $$
declare b public.production_batches;
begin
  select * into b from public.production_batches where id = p_id;
  if b.id is null then
    raise exception 'Batch not found';
  end if;
  if b.status in ('COMPLETED', 'CANCELLED') then
    raise exception 'Batch % is %. Reopen it first.', b.batch_no, lower(b.status::text);
  end if;
  return b;
end;
$$;

-- Create or edit a batch header and its paddy inputs
create or replace function public.save_production_batch(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'start_date')::date;
  b public.production_batches;
  l jsonb;
  v_cost numeric;
  v_total numeric := 0;
  v_kg numeric := 0;
  v_input_id uuid;
  s text;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  if jsonb_array_length(coalesce(p->'inputs', '[]'::jsonb)) = 0 then
    raise exception 'Add the paddy going into this batch';
  end if;

  if v_id is not null then
    perform public.require_open_batch(v_id);
    perform public.unpost_stock('PRODUCTION_INPUT', v_id);
    perform public.unpost_journal('PRODUCTION_INPUT', v_id);
    delete from public.production_inputs where batch_id = v_id;
    update public.production_batches set
      start_date = v_date, input_warehouse_id = (p->>'input_warehouse_id')::uuid,
      output_warehouse_id = (p->>'output_warehouse_id')::uuid, notes = p->>'notes', updated_at = now()
    where id = v_id returning * into b;
  else
    insert into public.production_batches (batch_no, start_date, input_warehouse_id, output_warehouse_id, notes)
    values (public.next_doc_no('BAT', v_date), v_date, (p->>'input_warehouse_id')::uuid,
      (p->>'output_warehouse_id')::uuid, p->>'notes')
    returning * into b;
    foreach s in array array['SOAKING', 'DRYING', 'MILLING'] loop
      insert into public.production_stages (batch_id, stage) values (b.id, s);
    end loop;
    update public.production_stages set start_date = v_date where batch_id = b.id and stage = 'SOAKING';
  end if;

  for l in select * from jsonb_array_elements(p->'inputs') loop
    insert into public.production_inputs (batch_id, item_id, lot_id, bags, qty_kg)
    values (b.id, (l->>'item_id')::uuid, nullif(l->>'lot_id', '')::uuid, coalesce((l->>'bags')::numeric, 0), (l->>'qty_kg')::numeric)
    returning id into v_input_id;
    v_cost := public.consume_stock(b.start_date, (l->>'item_id')::uuid, b.input_warehouse_id, (l->>'qty_kg')::numeric,
      coalesce((l->>'bags')::numeric, 0), 'PRODUCTION_INPUT', b.id, v_input_id, nullif(l->>'lot_id', '')::uuid, null, b.batch_no);
    update public.production_inputs set cost = v_cost where id = v_input_id;
    v_total := v_total + v_cost;
    v_kg := v_kg + (l->>'qty_kg')::numeric;
  end loop;

  update public.production_batches set input_kg = v_kg, input_cost = v_total where id = b.id;
  update public.production_stages set input_kg = coalesce(input_kg, v_kg) where batch_id = b.id and stage = 'SOAKING';

  perform public.post_journal(b.start_date, 'PRODUCTION_INPUT', b.id, 'Paddy into batch ' || b.batch_no, jsonb_build_array(
    public.jl_dr(public.system_account('WIP'), v_total),
    public.jl_cr(public.system_account('INVENTORY'), v_total)));
  return b.id;
end;
$$;

-- Update one stage; optionally move the batch to that stage
create or replace function public.save_production_stage(p jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  b public.production_batches := public.require_open_batch((p->>'batch_id')::uuid);
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  update public.production_stages set
    start_date = nullif(p->>'start_date', '')::date,
    end_date = nullif(p->>'end_date', '')::date,
    input_kg = nullif(p->>'input_kg', '')::numeric,
    output_kg = nullif(p->>'output_kg', '')::numeric,
    moisture_pct = nullif(p->>'moisture_pct', '')::numeric,
    notes = p->>'notes'
  where batch_id = b.id and stage = p->>'stage';

  if coalesce(p->>'set_status', '') in ('SOAKING', 'DRYING', 'MILLING') then
    update public.production_batches set status = (p->>'set_status')::public.production_status, updated_at = now()
    where id = b.id;
    -- the next stage starts where this one ended
    update public.production_stages set
      start_date = coalesce(start_date, nullif(p->>'end_date', '')::date, current_date),
      input_kg = coalesce(input_kg, nullif(p->>'output_kg', '')::numeric)
    where batch_id = b.id and stage = p->>'set_status';
  end if;
end;
$$;

create or replace function public.save_production_cost(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := coalesce(nullif(p->>'id', '')::uuid, gen_random_uuid());
  b public.production_batches := public.require_open_batch((p->>'batch_id')::uuid);
  c public.production_costs;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  perform public.unpost_journal('PRODUCTION_COST', v_id);
  delete from public.production_costs where id = v_id;

  insert into public.production_costs (id, batch_id, stage, cost_date, cost_head_id, amount, paid_account_id, party_id, notes)
  values (v_id, b.id, coalesce(p->>'stage', 'GENERAL'), (p->>'cost_date')::date, (p->>'cost_head_id')::uuid,
    (p->>'amount')::numeric, nullif(p->>'paid_account_id', '')::uuid, nullif(p->>'party_id', '')::uuid, p->>'notes')
  returning * into c;

  perform public.post_journal(c.cost_date, 'PRODUCTION_COST', c.id, 'Batch ' || b.batch_no || ' cost', jsonb_build_array(
    public.jl_dr(public.system_account('WIP'), c.amount, null, (select name from public.accounts where id = c.cost_head_id)),
    case when c.paid_account_id is not null
      then public.jl_cr(c.paid_account_id, c.amount)
      else public.jl_cr(public.system_account('PAYABLE'), c.amount, c.party_id) end));

  update public.production_batches
  set processing_cost = (select coalesce(sum(amount), 0) from public.production_costs where batch_id = b.id)
  where id = b.id;
  return c.id;
end;
$$;

create or replace function public.delete_production_cost(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_batch uuid;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  select batch_id into v_batch from public.production_costs where id = p_id;
  perform public.require_open_batch(v_batch);
  perform public.unpost_journal('PRODUCTION_COST', p_id);
  delete from public.production_costs where id = p_id;
  update public.production_batches
  set processing_cost = (select coalesce(sum(amount), 0) from public.production_costs where batch_id = v_batch)
  where id = v_batch;
end;
$$;

-- Complete a batch: p = {batch_id, completed_date, outputs: [{item_id, bags, bag_size_kg, qty_kg}]}
create or replace function public.complete_production_batch(p jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  b public.production_batches := public.require_open_batch((p->>'batch_id')::uuid);
  v_date date := (p->>'completed_date')::date;
  v_total numeric;
  v_weight_sum numeric := 0;
  v_use_value boolean;
  v_allocated numeric := 0;
  v_share numeric;
  v_n int;
  v_i int := 0;
  o record;
  v_lot uuid;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  if jsonb_array_length(coalesce(p->'outputs', '[]'::jsonb)) = 0 then
    raise exception 'Add the rice and by-products that came out of this batch';
  end if;

  delete from public.production_outputs where batch_id = b.id;
  insert into public.production_outputs (batch_id, item_id, bags, bag_size_kg, qty_kg)
  select b.id, (x->>'item_id')::uuid, coalesce((x->>'bags')::numeric, 0), coalesce((x->>'bag_size_kg')::numeric, 0), (x->>'qty_kg')::numeric
  from jsonb_array_elements(p->'outputs') x;

  v_total := b.input_cost + (select coalesce(sum(amount), 0) from public.production_costs where batch_id = b.id);

  -- split by value (qty x standard price); fall back to weight if no prices are set
  select sum(po.qty_kg * i.standard_price) into v_weight_sum
  from public.production_outputs po join public.items i on i.id = po.item_id where po.batch_id = b.id;
  v_use_value := coalesce(v_weight_sum, 0) > 0;
  if not v_use_value then
    select sum(qty_kg) into v_weight_sum from public.production_outputs where batch_id = b.id;
  end if;
  select count(*) into v_n from public.production_outputs where batch_id = b.id;

  for o in
    select po.*, i.standard_price from public.production_outputs po join public.items i on i.id = po.item_id
    where po.batch_id = b.id order by po.qty_kg * i.standard_price, po.qty_kg
  loop
    v_i := v_i + 1;
    if v_i = v_n then
      v_share := v_total - v_allocated;   -- last line takes the rounding remainder
    else
      v_share := round(v_total * (case when v_use_value then o.qty_kg * o.standard_price else o.qty_kg end) / v_weight_sum, 2);
    end if;
    v_allocated := v_allocated + v_share;
    v_lot := public.receive_stock(v_date, o.item_id, b.output_warehouse_id, o.qty_kg, o.bags, o.bag_size_kg,
      v_share / o.qty_kg, 'PRODUCTION', b.id, o.id, null, b.batch_no);
    update public.production_outputs set cost_share = v_share, unit_cost = round(v_share / o.qty_kg, 6), lot_id = v_lot
    where id = o.id;
  end loop;

  perform public.post_journal(v_date, 'PRODUCTION', b.id, 'Batch ' || b.batch_no || ' completed', jsonb_build_array(
    public.jl_dr(public.system_account('INVENTORY'), v_total),
    public.jl_cr(public.system_account('WIP'), v_total)));

  update public.production_batches set
    status = 'COMPLETED', completed_date = v_date,
    output_kg = (select sum(qty_kg) from public.production_outputs where batch_id = b.id),
    processing_cost = v_total - input_cost, updated_at = now()
  where id = b.id;
  update public.production_stages set end_date = coalesce(end_date, v_date),
    output_kg = coalesce(output_kg, (select sum(qty_kg) from public.production_outputs where batch_id = b.id))
  where batch_id = b.id and stage = 'MILLING';
end;
$$;

create or replace function public.reopen_production_batch(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  perform public.unpost_stock('PRODUCTION', p_id);
  perform public.unpost_journal('PRODUCTION', p_id);
  delete from public.production_outputs where batch_id = p_id;
  update public.production_batches set status = 'MILLING', completed_date = null, output_kg = 0, updated_at = now()
  where id = p_id;
end;
$$;

create or replace function public.delete_production_batch(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  c record;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  perform public.require_open_batch(p_id);
  for c in select id from public.production_costs where batch_id = p_id loop
    perform public.unpost_journal('PRODUCTION_COST', c.id);
  end loop;
  perform public.unpost_stock('PRODUCTION_INPUT', p_id);
  perform public.unpost_journal('PRODUCTION_INPUT', p_id);
  delete from public.production_batches where id = p_id;
end;
$$;

-- Batch summary: yield and cost per kg of main product (rice)
create or replace view public.v_production_batches with (security_invoker = true) as
select
  b.*,
  b.input_cost + b.processing_cost as total_cost,
  coalesce(o.rice_kg, 0) as rice_kg,
  coalesce(o.byproduct_kg, 0) as byproduct_kg,
  case when b.input_kg > 0 then round(100 * coalesce(o.rice_kg, 0) / b.input_kg, 2) end as rice_yield_pct,
  case when b.input_kg > 0 then round(100 * b.output_kg / b.input_kg, 2) end as total_yield_pct,
  case when coalesce(o.rice_kg, 0) > 0 then round(o.rice_cost / o.rice_kg, 4) end as rice_cost_per_kg,
  w1.name as input_warehouse_name, w2.name as output_warehouse_name
from public.production_batches b
left join (
  select po.batch_id,
    sum(case when i.category = 'RICE' then po.qty_kg else 0 end) as rice_kg,
    sum(case when i.category <> 'RICE' then po.qty_kg else 0 end) as byproduct_kg,
    sum(case when i.category = 'RICE' then po.cost_share else 0 end) as rice_cost
  from public.production_outputs po join public.items i on i.id = po.item_id
  group by po.batch_id
) o on o.batch_id = b.id
join public.warehouses w1 on w1.id = b.input_warehouse_id
join public.warehouses w2 on w2.id = b.output_warehouse_id;


-- ==== 0007_money.sql ====
-- 0007 Money: receipts, payments, expenses, other income, transfers, capital, drawings, loans
--
-- One table, one posting function. A bounced cheque has no accounting effect.
-- Receipts and payments are settled against open bills (sales / purchases): either the
-- bills the user picks, or automatically oldest first.

create table public.money_txns (
  id uuid primary key default gen_random_uuid(),
  txn_no text not null unique,
  txn_date date not null,
  -- RECEIPT, PAYMENT, EXPENSE, INCOME, TRANSFER, CAPITAL_IN, DRAWING,
  -- LOAN_TAKEN, LOAN_REPAY, LOAN_GIVEN, LOAN_RECOVER
  txn_type text not null check (txn_type in ('RECEIPT', 'PAYMENT', 'EXPENSE', 'INCOME', 'TRANSFER', 'CAPITAL_IN',
    'DRAWING', 'LOAN_TAKEN', 'LOAN_REPAY', 'LOAN_GIVEN', 'LOAN_RECOVER')),
  party_id uuid references public.parties(id),
  money_account_id uuid not null references public.accounts(id),   -- cash or bank
  counter_account_id uuid references public.accounts(id),          -- expense/income head, or transfer destination
  amount numeric(14,2) not null check (amount > 0),
  method text not null default 'CASH' check (method in ('CASH', 'BANK', 'CHEQUE')),
  cheque_no text,
  cheque_date date,
  cheque_status text check (cheque_status in ('PENDING', 'CLEARED', 'BOUNCED')),
  reference text,
  notes text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index on public.money_txns (txn_date);
create index on public.money_txns (party_id);
create index on public.money_txns (txn_type);

-- Which bills a receipt/payment settled
create table public.bill_settlements (
  id bigint generated always as identity primary key,
  money_txn_id uuid not null references public.money_txns(id) on delete cascade,
  sale_id uuid references public.sales(id) on delete cascade,
  purchase_id uuid references public.purchases(id) on delete cascade,
  amount numeric(14,2) not null check (amount > 0),
  constraint settlement_one_bill check ((sale_id is null) <> (purchase_id is null))
);

create index on public.bill_settlements (sale_id);
create index on public.bill_settlements (purchase_id);

-- Bill dues: total less paid at the time less later settlements less returns
create or replace view public.v_sale_dues with (security_invoker = true) as
select
  s.*, p.name as customer_name, p.name_bn as customer_name_bn,
  s.received_amount + coalesce(st.settled, 0) + coalesce(rt.returned, 0) as total_paid,
  s.total_amount - s.received_amount - coalesce(st.settled, 0) - coalesce(rt.returned, 0) as due_amount,
  current_date - s.sale_date as age_days
from public.sales s
join public.parties p on p.id = s.customer_id
left join (select sale_id, sum(amount) as settled from public.bill_settlements where sale_id is not null group by sale_id) st on st.sale_id = s.id
left join (select sale_id, sum(amount) as returned from public.sale_returns where sale_id is not null group by sale_id) rt on rt.sale_id = s.id;

create or replace view public.v_purchase_dues with (security_invoker = true) as
select
  pu.*, p.name as supplier_name, p.name_bn as supplier_name_bn, pu.supplier_total as total_amount,
  pu.paid_amount + coalesce(st.settled, 0) + coalesce(rt.returned, 0) as total_paid,
  pu.supplier_total - pu.paid_amount - coalesce(st.settled, 0) - coalesce(rt.returned, 0) as due_amount,
  current_date - pu.purchase_date as age_days
from public.purchases pu
join public.parties p on p.id = pu.supplier_id
left join (select purchase_id, sum(amount) as settled from public.bill_settlements where purchase_id is not null group by purchase_id) st on st.purchase_id = pu.id
left join (select purchase_id, sum(amount) as returned from public.purchase_returns where purchase_id is not null group by purchase_id) rt on rt.purchase_id = pu.id;

create or replace function public.post_money_txn(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  t public.money_txns;
  v_lines jsonb;
  v_label text;
begin
  select * into t from public.money_txns where id = p_id;
  if t.cheque_status = 'BOUNCED' then
    return;
  end if;

  if t.txn_type in ('RECEIPT', 'PAYMENT', 'LOAN_TAKEN', 'LOAN_REPAY', 'LOAN_GIVEN', 'LOAN_RECOVER') and t.party_id is null then
    raise exception 'Choose the party';
  end if;
  if t.txn_type in ('EXPENSE', 'INCOME', 'TRANSFER') and t.counter_account_id is null then
    raise exception 'Choose the account';
  end if;

  v_lines := case t.txn_type
    when 'RECEIPT' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(public.system_account('RECEIVABLE'), t.amount, t.party_id))
    when 'PAYMENT' then jsonb_build_array(
      public.jl_dr(public.system_account('PAYABLE'), t.amount, t.party_id), public.jl_cr(t.money_account_id, t.amount))
    when 'EXPENSE' then jsonb_build_array(
      public.jl_dr(t.counter_account_id, t.amount), public.jl_cr(t.money_account_id, t.amount))
    when 'INCOME' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(t.counter_account_id, t.amount))
    when 'TRANSFER' then jsonb_build_array(
      public.jl_dr(t.counter_account_id, t.amount), public.jl_cr(t.money_account_id, t.amount))
    when 'CAPITAL_IN' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(public.system_account('CAPITAL'), t.amount))
    when 'DRAWING' then jsonb_build_array(
      public.jl_dr(public.system_account('DRAWINGS'), t.amount), public.jl_cr(t.money_account_id, t.amount))
    when 'LOAN_TAKEN' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(public.system_account('LOAN_PAYABLE'), t.amount, t.party_id))
    when 'LOAN_REPAY' then jsonb_build_array(
      public.jl_dr(public.system_account('LOAN_PAYABLE'), t.amount, t.party_id), public.jl_cr(t.money_account_id, t.amount))
    when 'LOAN_GIVEN' then jsonb_build_array(
      public.jl_dr(public.system_account('LOAN_RECEIVABLE'), t.amount, t.party_id), public.jl_cr(t.money_account_id, t.amount))
    when 'LOAN_RECOVER' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(public.system_account('LOAN_RECEIVABLE'), t.amount, t.party_id))
  end;

  v_label := initcap(replace(lower(t.txn_type), '_', ' ')) || ' ' || t.txn_no;
  perform public.post_journal(t.txn_date, 'MONEY', t.id, coalesce(nullif(t.notes, ''), v_label), v_lines);
end;
$$;

-- Settle a receipt/payment against bills. p_allocations: [{sale_id|purchase_id, amount}] or null for oldest-first.
create or replace function public.settle_bills(p_id uuid, p_allocations jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  t public.money_txns;
  v_left numeric;
  v_take numeric;
  a jsonb;
  r record;
begin
  select * into t from public.money_txns where id = p_id;
  delete from public.bill_settlements where money_txn_id = p_id;
  if t.txn_type not in ('RECEIPT', 'PAYMENT') or t.cheque_status = 'BOUNCED' then
    return;
  end if;
  v_left := t.amount;

  if p_allocations is not null and jsonb_array_length(p_allocations) > 0 then
    for a in select * from jsonb_array_elements(p_allocations) loop
      v_take := least(coalesce((a->>'amount')::numeric, 0), v_left);
      continue when v_take <= 0;
      insert into public.bill_settlements (money_txn_id, sale_id, purchase_id, amount)
      values (p_id, nullif(a->>'sale_id', '')::uuid, nullif(a->>'purchase_id', '')::uuid, v_take);
      v_left := v_left - v_take;
    end loop;
    return;
  end if;

  if t.txn_type = 'RECEIPT' then
    for r in select id, due_amount from public.v_sale_dues
             where customer_id = t.party_id and due_amount > 0.005 order by sale_date, sale_no loop
      exit when v_left <= 0.005;
      v_take := least(r.due_amount, v_left);
      insert into public.bill_settlements (money_txn_id, sale_id, amount) values (p_id, r.id, v_take);
      v_left := v_left - v_take;
    end loop;
  else
    for r in select id, due_amount from public.v_purchase_dues
             where supplier_id = t.party_id and due_amount > 0.005 order by purchase_date, purchase_no loop
      exit when v_left <= 0.005;
      v_take := least(r.due_amount, v_left);
      insert into public.bill_settlements (money_txn_id, purchase_id, amount) values (p_id, r.id, v_take);
      v_left := v_left - v_take;
    end loop;
  end if;
end;
$$;

create or replace function public.save_money_txn(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'txn_date')::date;
  v_type text := p->>'txn_type';
  v_no text;
  v_method text := coalesce(p->>'method', 'CASH');
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');

  if v_id is not null then
    perform public.unpost_journal('MONEY', v_id);
    select txn_no into v_no from public.money_txns where id = v_id;
  else
    v_id := gen_random_uuid();
    v_no := public.next_doc_no(case v_type
      when 'RECEIPT' then 'RCV' when 'PAYMENT' then 'PAY' when 'EXPENSE' then 'EXP' when 'INCOME' then 'INC'
      when 'TRANSFER' then 'TRN' when 'CAPITAL_IN' then 'CAP' when 'DRAWING' then 'DRW' else 'LON' end, v_date);
  end if;

  if v_type = 'TRANSFER' and p->>'counter_account_id' = p->>'money_account_id' then
    raise exception 'Choose two different accounts for a transfer';
  end if;

  insert into public.money_txns (id, txn_no, txn_date, txn_type, party_id, money_account_id, counter_account_id, amount,
    method, cheque_no, cheque_date, cheque_status, reference, notes)
  values (v_id, v_no, v_date, v_type, nullif(p->>'party_id', '')::uuid, (p->>'money_account_id')::uuid,
    nullif(p->>'counter_account_id', '')::uuid, (p->>'amount')::numeric, v_method,
    p->>'cheque_no', nullif(p->>'cheque_date', '')::date,
    case when v_method = 'CHEQUE' then coalesce(nullif(p->>'cheque_status', ''), 'PENDING') end,
    p->>'reference', p->>'notes')
  on conflict (id) do update set
    txn_date = excluded.txn_date, txn_type = excluded.txn_type, party_id = excluded.party_id,
    money_account_id = excluded.money_account_id, counter_account_id = excluded.counter_account_id,
    amount = excluded.amount, method = excluded.method, cheque_no = excluded.cheque_no,
    cheque_date = excluded.cheque_date, cheque_status = excluded.cheque_status,
    reference = excluded.reference, notes = excluded.notes, updated_at = now();

  perform public.post_money_txn(v_id);
  perform public.settle_bills(v_id, p->'allocations');
  return v_id;
end;
$$;

create or replace function public.set_cheque_status(p_id uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  update public.money_txns set cheque_status = p_status, updated_at = now() where id = p_id and method = 'CHEQUE';
  perform public.unpost_journal('MONEY', p_id);
  perform public.post_money_txn(p_id);
  perform public.settle_bills(p_id, null);
end;
$$;

create or replace function public.delete_money_txn(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  perform public.unpost_journal('MONEY', p_id);
  delete from public.money_txns where id = p_id;
end;
$$;

create or replace view public.v_money_txns with (security_invoker = true) as
select
  t.*,
  m.name as money_account_name, m.subtype as money_account_subtype,
  c.name as counter_account_name,
  p.name as party_name
from public.money_txns t
join public.accounts m on m.id = t.money_account_id
left join public.accounts c on c.id = t.counter_account_id
left join public.parties p on p.id = t.party_id;


-- ==== 0008_reports.sql ====
-- 0008 Reports. These run with the caller's rights, so row-level security decides who can see them.

-- Ledger for one account (cash book, bank book, any account) or one party, with running balance.
-- Exactly one of p_account / p_party should be given.
create or replace function public.report_ledger(p_account uuid, p_party uuid, p_from date, p_to date)
returns table (
  row_no bigint, entry_date date, entry_id uuid, source_type text, source_id uuid,
  narration text, memo text, account_name text, party_name text,
  debit numeric, credit numeric, balance numeric
) language sql stable as $$
  with base as (
    select l.*, e.entry_date, e.source_type, e.source_id, e.narration, e.created_at
    from public.journal_lines l
    join public.journal_entries e on e.id = l.entry_id
    where (p_account is null or l.account_id = p_account)
      and (p_party is null or l.party_id = p_party)
  ),
  opening as (
    select coalesce(sum(debit - credit), 0) as bal from base where entry_date < p_from
  ),
  period as (
    select b.*, row_number() over (order by b.entry_date, b.created_at, b.id) as rn
    from base b where b.entry_date between p_from and p_to
  )
  select 0::bigint, p_from, null::uuid, 'OPENING', null::uuid, 'Opening balance', null, null, null,
    null::numeric, null::numeric, (select bal from opening)
  union all
  select p.rn, p.entry_date, p.entry_id, p.source_type, p.source_id, p.narration, p.memo,
    a.name, pa.name, p.debit, p.credit,
    (select bal from opening) + sum(p.debit - p.credit) over (order by p.rn)
  from period p
  join public.accounts a on a.id = p.account_id
  left join public.parties pa on pa.id = p.party_id
  order by 1
$$;

create or replace function public.report_trial_balance(p_to date)
returns table (account_id uuid, code text, name text, type public.account_type, subtype text, debit numeric, credit numeric)
language sql stable as $$
  select a.id, a.code, a.name, a.type, a.subtype,
    greatest(sum(l.debit - l.credit), 0), greatest(sum(l.credit - l.debit), 0)
  from public.accounts a
  join public.journal_lines l on l.account_id = a.id
  join public.journal_entries e on e.id = l.entry_id and e.entry_date <= p_to
  group by a.id
  having sum(l.debit - l.credit) <> 0
  order by a.code
$$;

-- Profit & loss: income shown positive, expenses positive
create or replace function public.report_profit_loss(p_from date, p_to date)
returns table (account_id uuid, code text, name text, type public.account_type, subtype text, amount numeric)
language sql stable as $$
  select a.id, a.code, a.name, a.type, a.subtype,
    case when a.type = 'INCOME' then sum(l.credit - l.debit) else sum(l.debit - l.credit) end
  from public.accounts a
  join public.journal_lines l on l.account_id = a.id
  join public.journal_entries e on e.id = l.entry_id and e.entry_date between p_from and p_to
  where a.type in ('INCOME', 'EXPENSE')
  group by a.id
  having sum(l.debit - l.credit) <> 0
  order by a.type desc, a.code
$$;

-- Balance sheet: assets positive, liabilities and equity positive; profit to date shown as one equity line
create or replace function public.report_balance_sheet(p_to date)
returns table (section text, account_id uuid, code text, name text, subtype text, amount numeric)
language sql stable as $$
  with bal as (
    select a.id, a.code, a.name, a.type, a.subtype, sum(l.debit - l.credit) as dr
    from public.accounts a
    join public.journal_lines l on l.account_id = a.id
    join public.journal_entries e on e.id = l.entry_id and e.entry_date <= p_to
    group by a.id
  )
  select type::text, id, code, name, subtype, case when type = 'ASSET' then dr else -dr end
  from bal where type in ('ASSET', 'LIABILITY', 'EQUITY') and dr <> 0
  union all
  select 'EQUITY', null, '3999', 'Profit / loss to date', 'PROFIT', coalesce(-sum(dr), 0)
  from bal where type in ('INCOME', 'EXPENSE')
  order by 1, 3
$$;

-- Day / period cash summary across all cash and bank accounts
create or replace function public.report_cash_summary(p_from date, p_to date)
returns table (account_id uuid, name text, subtype text, opening numeric, money_in numeric, money_out numeric, closing numeric)
language sql stable as $$
  select a.id, a.name, a.subtype,
    coalesce(sum(l.debit - l.credit) filter (where e.entry_date < p_from), 0),
    coalesce(sum(l.debit) filter (where e.entry_date between p_from and p_to), 0),
    coalesce(sum(l.credit) filter (where e.entry_date between p_from and p_to), 0),
    coalesce(sum(l.debit - l.credit) filter (where e.entry_date <= p_to), 0)
  from public.accounts a
  left join public.journal_lines l on l.account_id = a.id
  left join public.journal_entries e on e.id = l.entry_id
  where a.subtype in ('CASH', 'BANK') and a.is_active
  group by a.id
  order by a.subtype desc, a.code
$$;

-- Lot profit: each purchased or produced lot, following transfers to its child lots
create or replace view public.v_lot_profit with (security_invoker = true) as
with recursive tree as (
  select id as root_id, id as lot_id from public.lots where parent_lot_id is null
  union all
  select t.root_id, l.id from public.lots l join tree t on l.parent_lot_id = t.lot_id
),
alloc as (
  select t.root_id,
    sum(a.qty_kg) filter (where a.source_type = 'SALE') as sold_kg,
    sum(a.revenue) filter (where a.source_type = 'SALE') as revenue,
    sum(a.cost) filter (where a.source_type = 'SALE') as cost_of_sold,
    sum(a.qty_kg) filter (where a.source_type = 'PRODUCTION_INPUT') as milled_kg,
    sum(a.qty_kg) filter (where a.source_type in ('ADJUSTMENT', 'PURCHASE_RETURN')) as other_out_kg
  from tree t join public.lot_allocations a on a.lot_id = t.lot_id
  group by t.root_id
),
remain as (
  select t.root_id, sum(l.remaining_kg) as remaining_kg, sum(l.remaining_kg * l.unit_cost) as remaining_value
  from tree t join public.lots l on l.id = t.lot_id
  group by t.root_id
)
select
  l.id, l.lot_no, l.source_type, l.source_id, l.received_date, l.item_id, i.name as item_name, i.category,
  l.warehouse_id, w.name as warehouse_name,
  coalesce(pa.name, pb.batch_no) as source_label,
  l.qty_kg, l.unit_cost, round(l.qty_kg * l.unit_cost, 2) as total_cost,
  coalesce(a.sold_kg, 0) as sold_kg, coalesce(a.revenue, 0) as revenue, coalesce(a.cost_of_sold, 0) as cost_of_sold,
  coalesce(a.revenue, 0) - coalesce(a.cost_of_sold, 0) as profit,
  case when coalesce(a.revenue, 0) > 0 then round(100 * (a.revenue - a.cost_of_sold) / a.revenue, 2) end as margin_pct,
  coalesce(a.milled_kg, 0) as milled_kg, coalesce(a.other_out_kg, 0) as other_out_kg,
  coalesce(r.remaining_kg, 0) as remaining_kg, round(coalesce(r.remaining_value, 0), 2) as remaining_value
from public.lots l
join public.items i on i.id = l.item_id
join public.warehouses w on w.id = l.warehouse_id
left join alloc a on a.root_id = l.id
left join remain r on r.root_id = l.id
left join public.purchases pu on l.source_type = 'PURCHASE' and pu.id = l.source_id
left join public.parties pa on pa.id = pu.supplier_id
left join public.production_batches pb on l.source_type = 'PRODUCTION' and pb.id = l.source_id
where l.parent_lot_id is null;

-- Dashboard figures
create or replace function public.dashboard_stats(p_from date, p_to date)
returns jsonb language sql stable as $$
  select jsonb_build_object(
    'cash', (select coalesce(sum(l.debit - l.credit), 0) from public.journal_lines l join public.accounts a on a.id = l.account_id where a.subtype = 'CASH'),
    'bank', (select coalesce(sum(l.debit - l.credit), 0) from public.journal_lines l join public.accounts a on a.id = l.account_id where a.subtype = 'BANK'),
    'receivable', (select coalesce(sum(balance), 0) from public.v_party_balances where balance > 0),
    'payable', (select coalesce(-sum(balance), 0) from public.v_party_balances where balance < 0),
    'stock_value', (select coalesce(sum(remaining_kg * unit_cost), 0) from public.lots where remaining_kg > 0),
    'paddy_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'PADDY'),
    'rice_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'RICE'),
    'open_batches', (select count(*) from public.production_batches where status in ('SOAKING', 'DRYING', 'MILLING')),
    'sales', (select coalesce(sum(total_amount), 0) from public.sales where sale_date between p_from and p_to),
    'purchases', (select coalesce(sum(total_cost), 0) from public.purchases where purchase_date between p_from and p_to),
    'expenses', (select coalesce(sum(amount), 0) from public.money_txns where txn_type = 'EXPENSE' and txn_date between p_from and p_to and coalesce(cheque_status, '') <> 'BOUNCED'),
    'profit', (select coalesce(sum(case when type = 'INCOME' then amount else -amount end), 0) from public.report_profit_loss(p_from, p_to)),
    'pending_cheques', (select count(*) from public.money_txns where cheque_status = 'PENDING'),
    'trend', (
      select coalesce(jsonb_agg(jsonb_build_object('month', to_char(m, 'YYYY-MM'), 'sales', s, 'purchases', pu) order by m), '[]'::jsonb)
      from (
        select m,
          (select coalesce(sum(total_amount), 0) from public.sales where date_trunc('month', sale_date) = m) as s,
          (select coalesce(sum(total_cost), 0) from public.purchases where date_trunc('month', purchase_date) = m) as pu
        from generate_series(date_trunc('month', p_to::timestamp) - interval '5 months', date_trunc('month', p_to::timestamp), interval '1 month') m
      ) x
    )
  )
$$;


-- ==== 0009_security.sql ====
-- 0009 Security: row-level security, function permissions, audit triggers
--
-- Reading: any active signed-in user, except that OPERATOR cannot read the books (journal).
-- Writing master data: directly on the table, limited by role.
-- Writing documents (purchases, sales, money, production, stock): only through the save_*/delete_*
-- functions, which check the role themselves. The tables have no write policies at all.

do $$
declare t text;
begin
  foreach t in array array[
    'profiles', 'company_settings', 'doc_sequences', 'audit_log',
    'accounts', 'parties', 'items', 'warehouses',
    'journal_entries', 'journal_lines',
    'lots', 'stock_movements', 'lot_allocations', 'stock_transfers', 'stock_adjustments',
    'purchases', 'purchase_lines', 'sales', 'sale_lines', 'sale_returns', 'purchase_returns',
    'production_batches', 'production_inputs', 'production_stages', 'production_costs', 'production_outputs',
    'money_txns', 'bill_settlements'
  ] loop
    execute format('alter table public.%I enable row level security', t);
  end loop;

  -- read access for every active user
  foreach t in array array[
    'company_settings', 'accounts', 'parties', 'items', 'warehouses',
    'lots', 'stock_movements', 'lot_allocations', 'stock_transfers', 'stock_adjustments',
    'purchases', 'purchase_lines', 'sales', 'sale_lines', 'sale_returns', 'purchase_returns',
    'production_batches', 'production_inputs', 'production_stages', 'production_costs', 'production_outputs',
    'money_txns', 'bill_settlements'
  ] loop
    execute format('create policy "read %1$s" on public.%1$I for select to authenticated using (public.app_role() is not null)', t);
  end loop;

  -- the books: not for operators
  foreach t in array array['journal_entries', 'journal_lines'] loop
    execute format($p$create policy "read %1$s" on public.%1$I for select to authenticated
      using (public.has_role('ADMIN', 'ACCOUNTANT', 'VIEWER'))$p$, t);
  end loop;
end $$;

-- Profiles: everyone sees the team list; only admins change roles
create policy "read profiles" on public.profiles for select to authenticated
  using (id = auth.uid() or public.app_role() is not null);
create policy "admin updates profiles" on public.profiles for update to authenticated
  using (public.has_role('ADMIN')) with check (public.has_role('ADMIN'));

create policy "admin reads audit" on public.audit_log for select to authenticated using (public.has_role('ADMIN'));

create policy "admin updates settings" on public.company_settings for update to authenticated
  using (public.has_role('ADMIN')) with check (public.has_role('ADMIN'));

-- Master data
create policy "write accounts" on public.accounts for insert to authenticated with check (public.has_role('ADMIN', 'ACCOUNTANT'));
create policy "update accounts" on public.accounts for update to authenticated
  using (public.has_role('ADMIN', 'ACCOUNTANT')) with check (public.has_role('ADMIN', 'ACCOUNTANT'));
create policy "delete accounts" on public.accounts for delete to authenticated using (public.has_role('ADMIN') and not is_system);

create policy "write parties" on public.parties for insert to authenticated with check (public.has_role('ADMIN', 'ACCOUNTANT', 'OPERATOR'));
create policy "update parties" on public.parties for update to authenticated
  using (public.has_role('ADMIN', 'ACCOUNTANT', 'OPERATOR')) with check (public.has_role('ADMIN', 'ACCOUNTANT', 'OPERATOR'));
create policy "delete parties" on public.parties for delete to authenticated using (public.has_role('ADMIN'));

create policy "write items" on public.items for insert to authenticated with check (public.has_role('ADMIN', 'ACCOUNTANT'));
create policy "update items" on public.items for update to authenticated
  using (public.has_role('ADMIN', 'ACCOUNTANT')) with check (public.has_role('ADMIN', 'ACCOUNTANT'));
create policy "delete items" on public.items for delete to authenticated using (public.has_role('ADMIN'));

create policy "write warehouses" on public.warehouses for insert to authenticated with check (public.has_role('ADMIN', 'ACCOUNTANT'));
create policy "update warehouses" on public.warehouses for update to authenticated
  using (public.has_role('ADMIN', 'ACCOUNTANT')) with check (public.has_role('ADMIN', 'ACCOUNTANT'));
create policy "delete warehouses" on public.warehouses for delete to authenticated using (public.has_role('ADMIN'));

-- Internal functions: not callable from the app. Only the role-checked save/delete functions use them.
revoke execute on function
  public.handle_new_user(), public.next_doc_no(text, date), public.audit_row(),
  public.post_journal(date, text, uuid, text, jsonb), public.unpost_journal(text, uuid),
  public.post_party_opening(), public.post_account_opening(),
  public.receive_stock(date, uuid, uuid, numeric, numeric, numeric, numeric, text, uuid, uuid, uuid, text),
  public.consume_stock(date, uuid, uuid, numeric, numeric, text, uuid, uuid, uuid, numeric, text),
  public.unpost_stock(text, uuid),
  public.post_purchase(uuid), public.unpost_purchase(uuid),
  public.post_sale(uuid), public.unpost_sale(uuid),
  public.post_money_txn(uuid), public.settle_bills(uuid, jsonb),
  public.require_open_batch(uuid)
from public, anon, authenticated;

-- Callable document functions: signed-in users only (each checks the role itself)
revoke execute on function
  public.save_purchase(jsonb), public.delete_purchase(uuid),
  public.save_sale(jsonb), public.delete_sale(uuid),
  public.save_sale_return(jsonb), public.delete_sale_return(uuid),
  public.save_purchase_return(jsonb), public.delete_purchase_return(uuid),
  public.save_stock_transfer(jsonb), public.delete_stock_transfer(uuid),
  public.save_stock_adjustment(jsonb), public.delete_stock_adjustment(uuid),
  public.save_production_batch(jsonb), public.save_production_stage(jsonb),
  public.save_production_cost(jsonb), public.delete_production_cost(uuid),
  public.complete_production_batch(jsonb), public.reopen_production_batch(uuid), public.delete_production_batch(uuid),
  public.save_money_txn(jsonb), public.set_cheque_status(uuid, text), public.delete_money_txn(uuid)
from public, anon;
grant execute on function
  public.save_purchase(jsonb), public.delete_purchase(uuid),
  public.save_sale(jsonb), public.delete_sale(uuid),
  public.save_sale_return(jsonb), public.delete_sale_return(uuid),
  public.save_purchase_return(jsonb), public.delete_purchase_return(uuid),
  public.save_stock_transfer(jsonb), public.delete_stock_transfer(uuid),
  public.save_stock_adjustment(jsonb), public.delete_stock_adjustment(uuid),
  public.save_production_batch(jsonb), public.save_production_stage(jsonb),
  public.save_production_cost(jsonb), public.delete_production_cost(uuid),
  public.complete_production_batch(jsonb), public.reopen_production_batch(uuid), public.delete_production_batch(uuid),
  public.save_money_txn(jsonb), public.set_cheque_status(uuid, text), public.delete_money_txn(uuid)
to authenticated;

-- Audit trail
do $$
declare t text;
begin
  foreach t in array array[
    'profiles', 'company_settings', 'accounts', 'parties', 'items', 'warehouses',
    'purchases', 'sales', 'sale_returns', 'purchase_returns', 'money_txns',
    'production_batches', 'production_costs', 'stock_transfers', 'stock_adjustments'
  ] loop
    execute format('create trigger audit_%1$s after insert or update or delete on public.%1$I
      for each row execute function public.audit_row()', t);
  end loop;
end $$;


